import{St as e,Wt as t,Z as n,at as r,bt as i,it as a,jt as o,o as s,ot as c,st as l,tt as u,vt as d}from"./chunks/framework.DQt_9H6f.js";import{i as f}from"./chunks/theme.Dd2C0RTo.js";import{t as p}from"./chunks/DoctorSliceHero.B-rwq7r7.js";import{t as m}from"./chunks/ProgressLogHero.Da2nNVqx.js";var h={class:`mockup tps-wrap`,role:`group`,"aria-label":`Tool PATH search order`},g={class:`tps-grid`},_={class:`tps-list`},v={class:`tps-rank`},y={class:`tps-path`},b={class:`tps-fallback`},x=s({__name:`ToolPathSearchOrder`,setup(r){let s=[{title:`macOS`,paths:[`/opt/homebrew/bin`,`/usr/local/bin`,`/Library/TeX/texbin`,`/usr/texbin`,`MiKTeX Console.app/…/bin`,`~/bin`,`/usr/local/texlive/2024/…`,`~/texlive/* · ~/TinyTeX/bin`]},{title:`Windows`,paths:[`Program Files\\MiKTeX\\…\\x64`,`Program Files\\MiKTeX\\…\\bin`,`Program Files (x86)\\MiKTeX`,`%LOCALAPPDATA%\\…\\MiKTeX\\x64`,`%LOCALAPPDATA%\\…\\MiKTeX`,`MiKTeX 2.9\\…\\x64 (legacy)`,`%LOCALAPPDATA%\\MiKTeX\\…\\x64`,`C:\\texlive\\2024\\bin\\windows`]},{title:`Linux`,paths:[`/usr/local/bin`,`/usr/bin`,`/opt/miktex/bin`,`/snap/bin`,`/home/linuxbrew/.linuxbrew/bin`,`~/bin`,`texlive/<year>/bin/*`,`~/texlive/* · ~/TinyTeX`]}];return(r,p)=>{let m=e(`wa-icon`);return d(),a(`div`,h,[u(`div`,g,[(d(),a(n,null,i(s,(e,r)=>l(f,{key:r,class:`tps-col`,icon:`terminal`,title:e.title},{default:o(()=>[u(`ol`,_,[(d(!0),a(n,null,i(e.paths,(e,n)=>(d(),a(`li`,{key:n,class:`tps-row`},[u(`span`,v,t(n+1),1),u(`code`,y,t(e),1)]))),128))])]),_:2},1032,[`title`])),64))]),u(`div`,b,[l(m,{class:`tps-fb-ic`,library:`texra`,name:`search`}),p[0]||=u(`span`,{class:`tps-fb-tx`},[c(` Fallback: scans `),u(`code`,null,`texmf-dist/scripts`),c(` and runs `),u(`code`,null,`kpsewhich`),c(` to locate Perl helpers such as `),u(`code`,null,`latexdiff.pl`),c(`. `)],-1)])])}}},[[`__scopeId`,`data-v-60dc1e43`]]),S=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}`),C=Object.assign({name:`guide/troubleshooting.md`},{setup(e){return(e,t)=>(d(),a(`div`,null,[t[0]||=r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>This guide helps you diagnose and resolve common issues with TeXRA, whether an agent run stalls, a model refuses to connect, or the LaTeX toolchain is missing. Entries are grouped by category so you can find the one that matches your problem.</p><div class="tip custom-block"><p class="custom-block-title">CLI users</p><p>Most steps below describe the VS Code extension, but the underlying causes (missing dependencies, API keys, model settings) apply to every surface. From the terminal, run <code>texra doctor</code> to diagnose your environment, <code>texra models list</code> to confirm available models, and <code>/plugins</code> in <code>texra chat</code> to see each integration&#39;s state.</p></div><h2 id="installation-issues" tabindex="-1">Installation issues <a class="header-anchor" href="#installation-issues" aria-label="Permalink to “Installation issues”">​</a></h2><h3 id="extension-not-loading" tabindex="-1">Extension not loading <a class="header-anchor" href="#extension-not-loading" aria-label="Permalink to “Extension not loading”">​</a></h3><p><strong>Problem</strong>: TeXRA doesn&#39;t appear in the sidebar or shows errors during load.</p><p><strong>Solutions</strong>:</p><ol><li><p><strong>Check VS Code compatibility</strong>:</p><ul><li>Make sure you&#39;re running VS Code version 1.125 or newer</li><li>Update VS Code if needed</li></ul></li><li><p><strong>Verify installation</strong>:</p><ul><li>Open the Extensions view (Ctrl+Shift+X)</li><li>Search for &quot;TeXRA&quot;</li><li>If it is not installed or is disabled, install or enable it</li><li>Try reinstalling from the VSIX file</li></ul></li><li><p><strong>Check error logs</strong>:</p><ul><li>Open the Output panel (Ctrl+Shift+U)</li><li>Select &quot;TeXRA&quot; from the dropdown menu</li><li>Look for specific error messages</li></ul></li><li><p><strong>Check extension conflicts</strong>:</p><ul><li>Temporarily disable other extensions that might conflict</li><li>Restart VS Code and check whether TeXRA works</li></ul></li></ol><h3 id="dependency-installation-problems" tabindex="-1">Dependency installation problems <a class="header-anchor" href="#dependency-installation-problems" aria-label="Permalink to “Dependency installation problems”">​</a></h3><p><strong>Problem</strong>: Error messages about missing dependencies like LaTeX, Perl, or GraphicsMagick.</p><p>One command checks them all. <code>texra doctor</code> probes the LaTeX toolchain (plus Node, model access, and usage logging) and says exactly what is missing and how to fix it:</p>`,11),l(p,{rows:[{state:`pass`,name:`LaTeX latexmk`,message:`LaTeX build orchestration`},{state:`pass`,name:`LaTeX pdflatex`,message:`PDFLaTeX compiler`},{state:`warn`,name:`LaTeX latexdiff`,message:`latexdiff was not found on PATH.`,hint:`Install latexdiff: sudo apt-get install -y latexdiff`}]}),t[1]||=r(`<p><strong>Solutions</strong>:</p><ol><li><p><strong>Verify dependencies manually</strong>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">latexmk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # or pdflatex --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">perl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # For GraphicsMagick</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # For Ghostscript</span></span></code></pre></div></li><li><p><strong>Check the PATH environment</strong>:</p><ul><li>Make sure installation directories are in your system PATH</li><li>Restart your terminal and VS Code after updating PATH</li></ul></li></ol><ul><li>When you launch VS Code from the system menu or Finder, it may inherit a minimal PATH. TeXRA searches common locations in the following order:</li></ul>`,3),l(x),t[2]||=r(`<p><strong>macOS:</strong></p><ol><li><code>/opt/homebrew/bin</code> (Apple Silicon Homebrew)</li><li><code>/usr/local/bin</code> (Intel Homebrew and general tools)</li><li><code>/Library/TeX/texbin</code> (MacTeX symlink)</li><li><code>/usr/texbin</code> (legacy MacTeX location)</li><li><code>/Applications/MiKTeX Console.app/Contents/bin</code> (MiKTeX app bundle)</li><li><code>~/bin</code> (MiKTeX default symlink target)</li><li><code>~/.local/bin</code> (user-local tools such as Claude Code&#39;s native installer)</li><li>Versioned TeX Live directories (e.g., <code>/usr/local/texlive/2024/bin/universal-darwin</code>)</li><li>User-specific installations in <code>~/texlive/*/bin/*</code> and <code>~/TinyTeX/bin/*</code></li></ol><p><strong>Windows:</strong></p><ol><li><code>C:\\Program Files\\MiKTeX\\miktex\\bin\\x64</code> (64-bit MiKTeX)</li><li><code>C:\\Program Files\\MiKTeX\\miktex\\bin</code> (32-bit MiKTeX)</li><li><code>C:\\Program Files\\MiKTeX 2.9\\miktex\\bin\\x64</code> and <code>C:\\Program Files\\MiKTeX 2.9\\miktex\\bin</code> (legacy MiKTeX 2.9)</li><li><code>C:\\Program Files (x86)\\MiKTeX\\miktex\\bin</code> and <code>C:\\Program Files (x86)\\MiKTeX 2.9\\miktex\\bin</code> (32-bit on 64-bit Windows)</li><li><code>C:\\Strawberry\\perl\\bin</code> (Strawberry Perl)</li><li><code>C:\\Program Files\\Git\\cmd</code> and <code>C:\\Program Files (x86)\\Git\\cmd</code> (Git for Windows)</li><li>Ghostscript in <code>C:\\Program Files\\gs\\*\\bin</code> and <code>C:\\Program Files (x86)\\gs\\*\\bin</code> (newest version first)</li><li><code>%LOCALAPPDATA%\\Programs\\MiKTeX\\miktex\\bin\\x64</code> and <code>%LOCALAPPDATA%\\Programs\\MiKTeX\\miktex\\bin</code> (user MiKTeX installation)</li><li><code>%LOCALAPPDATA%\\Programs\\MiKTeX 2.9\\miktex\\bin\\x64</code> and <code>%LOCALAPPDATA%\\Programs\\MiKTeX 2.9\\miktex\\bin</code> (legacy user MiKTeX 2.9)</li><li><code>%LOCALAPPDATA%\\MiKTeX\\miktex\\bin\\x64</code> and <code>%LOCALAPPDATA%\\MiKTeX\\miktex\\bin</code> (user MiKTeX without Programs subfolder)</li><li><code>%LOCALAPPDATA%\\Programs\\Git\\cmd</code> (Git for Windows installed per user)</li><li>Scoop <code>shims</code> and <code>apps\\*\\current</code> directories (when Scoop is installed)</li><li>MSYS2 <code>usr\\bin</code>, <code>mingw64\\bin</code>, and <code>mingw32\\bin</code> under <code>C:\\msys64</code>, <code>C:\\msys32</code>, or <code>%MSYS2_HOME%</code> (when <code>perl.exe</code> exists there)</li><li>TeX Live&#39;s bundled Perl in <code>C:\\texlive\\*\\tlpkg\\tlperl\\bin</code> (and under <code>%USERPROFILE%\\texlive</code>)</li><li>Versioned TeX Live directories (e.g., <code>C:\\texlive\\2024\\bin\\windows</code>)</li><li>User-specific installations in <code>%USERPROFILE%\\texlive\\*\\bin\\*</code> and <code>%USERPROFILE%\\TinyTeX\\bin\\*</code></li></ol><p><strong>Linux:</strong></p><ol><li><code>/usr/local/bin</code></li><li><code>/usr/bin</code></li><li><code>/opt/miktex/bin</code> (MiKTeX installed via APT/AUR)</li><li><code>/snap/bin</code> (Ubuntu snap packages)</li><li><code>/home/linuxbrew/.linuxbrew/bin</code> (Linuxbrew)</li><li><code>~/bin</code> (MiKTeX default symlink target)</li><li><code>~/.local/bin</code> (user-local tools such as Claude Code&#39;s native installer)</li><li>Versioned TeX Live directories</li><li>User-specific installations</li></ol><p>Opening VS Code from a configured terminal provides the most reliable environment.</p><ol start="3"><li><p><strong>Manual installation</strong>:</p><ul><li>Follow the steps in the <a href="/guide/installation.html">installation guide</a></li><li>Use the recommended installation methods for your OS</li></ul></li><li><p><strong>Fix permissions issues</strong>:</p><ul><li>Make sure you have permission to run these tools</li><li>On macOS/Linux, check file permissions with <code>ls -la</code></li></ul></li></ol><h2 id="api-connection-issues" tabindex="-1">API connection issues <a class="header-anchor" href="#api-connection-issues" aria-label="Permalink to “API connection issues”">​</a></h2><h3 id="api-key-problems" tabindex="-1">API key problems <a class="header-anchor" href="#api-key-problems" aria-label="Permalink to “API key problems”">​</a></h3><p><strong>Problem</strong>: Error messages related to API keys or authentication failures.</p><p><strong>Solutions</strong>:</p><ol><li><p><strong>Verify API keys</strong>:</p><ul><li>VS Code extension: open <strong>Settings → Models → API keys</strong> and re-enter the key for the affected provider</li><li>CLI: run <code>texra setup</code> to add a provider API key, or set the provider&#39;s API-key environment variable (or connect a provider subscription with <code>texra auth chatgpt login</code>)</li></ul></li><li><p><strong>Check API key validity</strong>:</p><ul><li>Verify your API keys are active in the provider dashboards</li><li>Check for billing issues or usage limits</li></ul></li><li><p><strong>Network issues</strong>:</p><ul><li>Make sure your network allows connections to API endpoints</li><li>Check whether a firewall or network policy is blocking the connection</li></ul></li><li><p><strong>Provider status</strong>:</p><ul><li>Check the status pages for OpenAI, Anthropic, or Google</li><li>Temporary API outages may cause connection issues</li></ul></li></ol><h2 id="document-processing-issues" tabindex="-1">Document processing issues <a class="header-anchor" href="#document-processing-issues" aria-label="Permalink to “Document processing issues”">​</a></h2><h3 id="latex-compilation-and-diff-errors" tabindex="-1">LaTeX compilation and diff errors <a class="header-anchor" href="#latex-compilation-and-diff-errors" aria-label="Permalink to “LaTeX compilation and diff errors”">​</a></h3><ul><li><strong>Check the toolchain</strong>: Run <code>texra doctor</code> to confirm <code>latexmk</code>, <code>pdflatex</code>, <code>bibtex</code>, <code>biber</code>, <code>latexdiff</code>, and <code>latexindent</code> are found on <code>PATH</code>.</li><li><strong>Verify standalone compilation</strong>: Make sure the original <code>.tex</code> document compiles cleanly outside of TeXRA before running a diff or extraction task.</li><li><strong>Missing LaTeX packages</strong>: Install missing style files with <code>tlmgr install &lt;pkg&gt;</code> (TeX Live) or the MiKTeX Console.</li><li><strong>Diff fails to compile</strong>: Complex custom macros or unclosed math environments can conflict with <code>latexdiff</code> markup. Format both files first (<code>latexindent</code> or <code>tex-fmt</code>), or lower <strong>Math markup in diffs</strong> on <strong>Settings → LaTeX → Edit previews</strong>.</li></ul><h3 id="tikz-and-image-processing-errors" tabindex="-1">TikZ and image processing errors <a class="header-anchor" href="#tikz-and-image-processing-errors" aria-label="Permalink to “TikZ and image processing errors”">​</a></h3><ul><li><strong>Verify Ghostscript and GraphicsMagick / ImageMagick</strong>: Rasterizing PDFs for models without native PDF support requires both tools (<code>gm version</code> or <code>magick --version</code>, and <code>gs --version</code>).</li><li><strong>Custom TikZ packages or macros</strong>: Add custom packages to <code>&quot;texra.latex.tikzTemplate&quot;</code> and custom style paths to <code>&quot;texra.latex.tikzInputDirectory&quot;</code> in <code>.texra/config.json</code> (see <a href="./tikz-figures.html#customizing-tikz-processing">TikZ figures</a>).</li></ul><h2 id="ai-model-and-output-issues" tabindex="-1">AI model and output issues <a class="header-anchor" href="#ai-model-and-output-issues" aria-label="Permalink to “AI model and output issues”">​</a></h2><h3 id="timeouts-context-limits-or-weak-results" tabindex="-1">Timeouts, context limits, or weak results <a class="header-anchor" href="#timeouts-context-limits-or-weak-results" aria-label="Permalink to “Timeouts, context limits, or weak results”">​</a></h3><ul><li><strong>Rate limits and quota</strong>: Check your provider dashboard if requests fail with quota or billing errors.</li><li><strong>Large documents</strong>: If a run times out or hits the output token limit on a long <code>.tex</code> file, split the file into per-section inputs.</li><li><strong>Slow turnaround</strong>: Programs run multi-pass reasoning and can take 10–30 minutes on frontier reasoning models. For quick edits, pick a faster model (<code>google/gemini-3.8-flash</code>, <code>anthropic/claude-haiku-5-5</code>, <code>deepseek/deepseek-flash</code>, or <code>openai/gpt-6-luna</code>), or ask the assistant in a chat instead.</li><li><strong>Stronger reasoning</strong>: For hard derivations, proofs, or deep manuscript reviews, use a flagship model (<code>anthropic/claude-fable-5-2</code>, <code>anthropic/claude-opus-5-5</code>, <code>openai/gpt-6.2-astra</code>, <code>openai/gpt-6.2-sol</code>, or <code>google/gemini-4-neon</code>). The assistant can also start a program with a critic reviewing each revision (<code>args: { reflect: true }</code>).</li></ul><h3 id="high-memory-use-in-long-cli-sessions" tabindex="-1">High memory use in long CLI sessions <a class="header-anchor" href="#high-memory-use-in-long-cli-sessions" aria-label="Permalink to “High memory use in long CLI sessions”">​</a></h3><p><strong>Problem</strong>: A <code>texra</code> session that has run for days, or launched many subagents, slows down and eventually exits with a <code>JavaScript heap out of memory</code> error.</p><p><strong>Solutions</strong>:</p><ol><li><p><strong>Update TeXRA</strong>: 0.40.8 and later release the per-subagent and per-request state that earlier versions kept for the whole session.</p></li><li><p><strong>Raise the heap limit</strong> for very long runs. Node caps the heap at a few gigabytes by default:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NODE_OPTIONS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--max-old-space-size</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8192</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span></span></code></pre></div></li><li><p><strong>Capture a heap snapshot</strong> if memory still grows, so the retained objects can be inspected in Chrome DevTools:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NODE_OPTIONS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--heapsnapshot-near-heap-limit</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span></span></code></pre></div><p>Node writes a <code>.heapsnapshot</code> file into the working directory right before it would run out of memory. Attach it to a bug report.</p></li></ol><h2 id="debugging-tips" tabindex="-1">Debugging tips <a class="header-anchor" href="#debugging-tips" aria-label="Permalink to “Debugging tips”">​</a></h2><h3 id="using-the-tasks-view" tabindex="-1">Using the Tasks view <a class="header-anchor" href="#using-the-tasks-view" aria-label="Permalink to “Using the Tasks view”">​</a></h3><p>The Tasks view is your main debugging tool in VS Code. Read the <a href="./progress-board.html">Tasks view guide</a> for a full walkthrough.</p><ol><li><strong>Open the Tasks view</strong>: Select the TeXRA icon in the Secondary Side Bar and click <strong>Tasks</strong>, or run <strong>TeXRA: Show Tasks</strong> from the Command Palette.</li><li><strong>Inspect logs</strong>: Entries are color-coded by severity (green for info/success, yellow for warnings, red for errors) and expand to show nested tool calls and model responses:</li></ol>`,29),l(m),t[3]||=r(`<p class="hero-caption">The Tasks view color-codes every entry by severity (green info/success, yellow warnings, red errors), with task-id chips and expandable nested detail.</p><ol start="3"><li><strong>Copy diagnostics</strong>: Select <code>⋯</code> → <strong>Copy diagnostics</strong> on a task header to copy the task ID, model, status, output paths, and any compile errors for a bug report.</li></ol><h3 id="getting-support" tabindex="-1">Getting support <a class="header-anchor" href="#getting-support" aria-label="Permalink to “Getting support”">​</a></h3><ul><li><strong>GitHub Issues</strong>: Search or open an issue on <a href="https://github.com/LionSR/TeXRA/issues" target="_blank" rel="noreferrer">LionSR/TeXRA</a> with your OS, TeXRA version, reproduction steps, and <code>texra doctor</code> or <strong>Copy diagnostics</strong> output.</li><li><strong>Email</strong>: For private reports, write to <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a>.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><p>If you&#39;ve resolved your issue or want to learn more about TeXRA:</p><ul><li><a href="/guide/best-practices.html">Best practices</a>: learn how to use TeXRA effectively</li><li><a href="/guide/configuration.html">Configuration</a>: customize TeXRA for your needs</li><li><a href="/guide/programs.html">The assistant and programs</a>: what TeXRA can do</li></ul>`,7)]))}});export{S as __pageData,C as default};